package fr.gemsofrod.encyclopedie.data

/** Traductions Es des fiches météorites (nom, descriptions, intérêt en joaillerie). */
object MeteoriteTranslationsEs {
    val data: Map<String, MeteoriteTranslation> = mapOf(
        "meteorite-gibeon" to MeteoriteTranslation(
            nom = "Gibeon",
            descriptionCourte = "Una lluvia de fragmentos caída en Namibia hace milenios, convertida en la referencia mundial de la joyería meteorítica.",
            descriptionLongue = "Descubierto por el pueblo nama de Namibia mucho antes de su reconocimiento científico en 1836, Gibeon debe su fama a sus magníficas figuras de Widmanstätten: un entramado geométrico de kamacita y taenita, invisible a simple vista, que se revela mediante un simple ataque con ácido nítrico sobre una superficie pulida. Su extenso campo de dispersión lo ha convertido en el meteorito ferroso más disponible y más trabajado del mundo, tanto en colgantes como en hojas de cuchillo de autor.",
            interetJoaillerie = "Elevado: colgantes, gemelos, hojas de cuchillo. El meteorito ferroso más utilizado en joyería."
        ),
        "meteorite-sikhote-alin" to MeteoriteTranslation(
            nom = "Sikhote-Alin",
            descriptionCourte = "La lluvia de hierro más espectacular del siglo XX, filmada en pleno día sobre la taiga rusa.",
            descriptionLongue = "El 12 de febrero de 1947, una masa ferrosa de unas veinte toneladas estalló en pleno vuelo sobre los montes Sijoté-Alín, en el Extremo Oriente ruso, esparciendo miles de fragmentos a lo largo de varios kilómetros cuadrados. A diferencia de la mayoría de las caídas históricas, esta fue observada y documentada casi en directo. Los individuos, cubiertos de los característicos regmaglitos propios de una combustión atmosférica violenta, se encuentran hoy entre los meteoritos de colección más abundantes y reconocibles del mundo.",
            interetJoaillerie = "Medio a elevado: la caída mejor documentada del siglo XX, con fuerte demanda de coleccionistas por sus individuos de formas escultóricas."
        ),
        "meteorite-campo-del-cielo" to MeteoriteTranslation(
