        "meteorite-peekskill" to MeteoriteTranslation(
            nom = "Peekskill",
            descriptionCourte = "El meteorito que impactó contra un Chevrolet Malibu aparcado en Nueva York, filmado en pleno vuelo por espectadores de un partido de fútbol americano.",
            descriptionLongue = "El 9 de octubre de 1992, un bólido que cruzó el cielo de varios estados de Estados Unidos —filmado por numerosos testigos durante partidos de fútbol americano escolar— terminó su trayecto con el impacto de un fragmento de 12 kg en la parte trasera de un Chevrolet Malibu aparcado en Peekskill, Nueva York. La anécdota hizo mundialmente célebre a esta condrita; los fragmentos, escasos, se conservan sobre todo en bruto para preservar su costra de fusión, garantía de autenticidad y valor en colección.",
            interetJoaillerie = "Medio: anécdota muy conocida (el bólido impactó contra un coche aparcado), de gran valor narrativo en colección."
        ),
        "meteorite-nwa-chondrite" to MeteoriteTranslation(
            nom = "Condrita del Sáhara (NWA genérica)",
            descriptionCourte = "Los innumerables hallazgos saharianos, catalogados bajo la denominación genérica \"Northwest Africa\", que abastecen la mayor parte del mercado de la condrita.",
            descriptionLongue = "Desde la década de 1990, la aridez y la legibilidad del desierto del Sáhara lo han convertido en el terreno de hallazgo de meteoritos más prolífico del mundo, catalogados colectivamente bajo la denominación \"Northwest Africa\" seguida de un número (NWA 1, NWA 869...). Estas condritas ordinarias, de clasificación variable y a menudo menos documentadas que una caída observada, ofrecen no obstante la puerta de entrada más asequible a la colección y el corte de meteoritos pétreos.",
            interetJoaillerie = "Económica, con gran disponibilidad: la opción de entrada más habitual para descubrir la condrita tallada."
