            descriptionLongue = "Caído en febrero de 1969 sobre Chihuahua, Allende dispersó varias toneladas de fragmentos en un vasto territorio, lo que ha convertido a esta caída en una de las más estudiadas del mundo. Sus inclusiones blanquecinas, ricas en calcio y aluminio, se cuentan entre los sólidos más antiguos conocidos del sistema solar, anteriores en varios millones de años a la formación de la Tierra. Al igual que Murchison, su fragilidad reserva su uso a la investigación y la colección, nunca a la talla.",
            interetJoaillerie = "Nulo en joyería; contiene algunos de los sólidos más antiguos conocidos del sistema solar."
        ),
        "meteorite-hoba" to MeteoriteTranslation(
            nom = "Hoba",
            descriptionCourte = "El mayor meteorito conocido en la Tierra, que permanece exactamente donde cayó hace unos 80.000 años.",
            descriptionLongue = "Descubierto en 1920 en una granja namibia, Hoba es, con sus aproximadamente sesenta toneladas, el meteorito más masivo jamás recuperado intacto en la Tierra; su tamaño y su forma plana le permitieron no hundirse ni fragmentarse en el impacto. Declarado monumento nacional de Namibia, nunca ha sido trasladado ni cortado y todavía puede visitarse en su lugar original de caída; figura aquí como referencia cultural, no como material disponible.",
            interetJoaillerie = "Nulo (no comercializado); interés puramente museístico y turístico."
        ),
        "meteorite-willamette" to MeteoriteTranslation(
