            descriptionLongue = "Descubierto en el siglo XIX en Oregón, esta masa de más de 15 toneladas es venerada desde hace generaciones por el pueblo clackamas bajo el nombre de Tomanowos, un visitante celeste portador de sanación. Expuesto hoy en el American Museum of Natural History en virtud de un acuerdo con la tribu, nunca ha sido objeto de corte comercial y nunca lo será: figura aquí por su importancia histórica y cultural, no como material lapidario.",
            interetJoaillerie = "Nulo comercialmente; patrimonio cultural fundamental para el pueblo clackamas."
        ),
        "meteorite-ensisheim" to MeteoriteTranslation(
